ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_meet_3"] = {
{"fw_l23_sv_hospital_rumor","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"People say the hospital in Brandenburg took everybody",2,"And then?",1,"And then the lights went out",2,"Then nobody's coming back out of there"}},
{"fw_l23_sv_nobody_comes","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,10|mood=angry|out=part",{1,"I keep waiting for someone in charge to show up",2,"I stopped waiting on Wednesday",1,"What did you do instead?",2,"Moved my family out of the house and onto the hill"}},
{"fw_l23_sv_prayer","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|out=part",{1,"Mind if I say a prayer before we go on?",2,"Go ahead",1,"Lord, watch over everyone we couldn't - amen",2,"Amen"}},
{"fw_l23_sv_wrong_turn","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=funny|out=part",{1,"Is this the way to Ekron?",2,"No, you're about nine miles off",1,"I've been following signs",2,"The signs got moved, somebody wanted to confuse people"}},
{"fw_l23_sv_swap_stories","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=sad|out=part",{1,"Tell me about your family...",2,"Two boys, six and eight",1,"Where are they now?",2,"Safe, somewhere, I've got to believe that"}},
{"fw_l23_sv_zombie_word","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=funny|out=walk",{1,"Some kid back there called them zombies",2,"That's from the movies",1,"He seemed very sure",2,"Kids tend to be, I wish I could be sure of anything"}},
{"fw_l23_sv_gunshot_nearby","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"That shot, was it you?",2,"No, I thought it was you",1,"Then someone else is out there",2,"Let's get inside before we find out who"}},
{"fw_l23_sv_can_opener","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=funny|out=part",{1,"I have a can of peaches and no can opener",2,"Funny... I got a can opener and no peaches",1,"We should talk",2,"We should have a picnic"}},
{"fw_l23_sv_pharmacy","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=calm|out=part",{1,"The pharmacy on Main has been picked clean",2,"I know, I went yesterday",1,"Did you find anything?",2,"A box of bandages and a coloring book"}},
{"fw_l23_sv_walk_together","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|world=water|out=walk",{1,"Which way are you headed?",2,"South, toward the river - you?",1,"Same, it would be safer in numbers",2,"Agreed - keep your pack tight"}},
{"fw_l23_sv_hide_the_light","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=stay1",{1,"Put that lantern out, they come to light",2,"Sorry, I didn't know",1,"Use a candle behind a blanket if you must",2,"Got it!"}},
{"fw_l23_sv_funeral","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=sad|out=part",{1,"We buried my grandmother in the backyard last night",2,"I'm sorry",1,"I said the Lord's Prayer, I couldn't remember the second half...",2,"He knows what you meant"}},
{"fw_l23_sv_hot_weather","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=funny|world=vehicle|out=part",{1,"Hot as blazes today",2,"Could be worse, could be a dozen of them in the trunk of the car",1,"Don't make me check the trunk",2,"It's been a very strange week"}},
{"fw_l23_sv_radio_voice","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|hour=16,5|mood=warm|out=part",{1,"There's a woman on the shortwave who reads bedtime stories every night at nine",2,"To who?",1,"Whoever's listening, she says it's for the kids",2,"I'll tune in tonight, I could use a bedtime story"}},
{"fw_l23_sv_bad_feeling","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|world=window,road|out=part",{1,"Something doesn't feel right about the house across the road",2,"Why?",1,"Curtains moved when we passed",2,"Then we don't stop there, we keep walking"}},
{"fw_l23_sv_pickup_cache","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=calm|out=walk",{1,"There's a pickup full of canned goods behind the church - nobody around",2,"Is it a trap?",1,"I thought so too, we watched it two days",2,"Then I'll help you load it"}},
{"fw_l23_sv_whats_your_name","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|out=part",{1,"I never asked your name",2,"Darlene",1,"Mine's Cal, good to meet you, Darlene",2,"Likewise, I wasn't going to remember it otherwise"}},
{"fw_l23_sv_keep_moving","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|hour=16,5|mood=calm|out=walk",{1,"We should get going before dark",2,"Which way?",1,"East, along the tracks",2,"I'll watch the right side if you watch the left"}},
{"fw_l23_sv_the_horde","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"Did you see the crowd by the school?",2,"Hundreds, all turned the same direction",1,"Which direction?",2,"Toward the bell! Someone must have rung it"}},
{"fw_l23_sv_we_were_neighbors","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=sad|world=door|out=part",{1,"I think you lived two doors down from my sister",2,"On Pine? That's me",1,"She talked about you, said you had the best roses",2,"The roses - Lord, I forgot about the roses..."}},
{"fw_l23_sv_boredom","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=funny|out=part",{1,"What would you read if you could find a book?",2,"Even a Reader's Digest from 1988",1,"I'd settle for that",2,"There was a joke in one that I never did get"}},
{"fw_l23_t3f_trucks_north","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=grim|out=part",{1,"Your trucks went north all night - where were they going?",3,"I couldn't say",2,"Away from us, anyway",3,"Away from a lot of people, ma'am",1,"And the ones who stayed?",3,"Are the ones I'm here for"}},
{"fw_l23_t3f_water_buffalo","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=calm|world=road|out=stay3",{3,"If we find a working water tank, how would we keep a crowd from rushing it?",1,"Start by checking the water before promising anybody a jug",2,"Then work out where people would line up?",3,"Somewhere we could see each other, without blocking a way out",1,"How long could we keep it up?",3,"Only as long as there was water we could actually spare"}},
{"fw_l23_t3f_hospital_trouble","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=fear|out=part",{1,"We tried to go to the hospital",2,"It's overrun!",3,"Do not go back there!",1,"What's inside?",2,"The sick ones",3,"All of them"}},
{"fw_l23_t3f_lost_my_boots","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,14|mood=funny|world=water|out=part",{1,"I lost my boots in the creek",2,"I wish I had a spare pair to offer",3,"A surplus store might be worth checking, if you find one",1,"And if nothing fits?",3,"Don't let somebody tell you every foot's a ten. Bad boots can make things worse",2,"I'd rather help you look than promise you a pair I haven't got"}},
{"fw_l23_t3f_listening_post","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,12|mood=calm|out=walk",{3,"I need two civilians to relay messages between houses",1,"I'll do it",2,"So will I",3,"Use the alleys, stay out of sight",1,"Where do we report?",3,"To me at the school"}},
{"fw_l23_t3f_sniper_nest","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=calm|world=fence|out=stay3",{3,"We've set up a sniper position on the grain elevator",1,"Is it safe to be nearby?",2,"What if you miss?",3,"I don't miss",1,"Ha, ok",3,"Stay clear of the fence line"}},
{"fw_l23_t3f_prayer_in_dark","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,14|mood=warm|out=part",{1,"Would you say a few words for the ones we lost?",3,"I'm not clergy",2,"Anything will do",3,"... May they rest",1,"Amen",2,"Amen"}},
{"fw_l23_t3f_missing_kid_sweep","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=sad|out=walk",{1,"My boy's missing, brown hair, blue jacket",3,"We'll sweep the school grounds...",2,"I'll help",3,"Stay with my squad",1,"Please find him",3,"Moving out"}},
{"fw_l23_t3f_deserters","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=angry|out=part",{1,"Some men in uniforms robbed our house last night",3,"Describe them!",2,"One had a scar on his chin",3,"Not one of mine!",1,"Then who?",3,"Someone who took a uniform from a dead man"}},
{"fw_l23_t3f_dont_go_to_church","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|hour=16,5|mood=grim|out=stay3",{3,"Avoid the church on Main, it's been compromised",1,"But we pray there",2,"What's inside?",3,"A dozen of the sick ones",1,"Dear God",3,"Pray at home tonight"}},
{"fw_l23_t3f_candles","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,14|mood=warm|out=part",{1,"We made candles from lard",2,"They smell dreadful",3,"They work",1,"Try one",2,"It's lovely, actually",3,"I'll take one for the barracks"}},
{"fw_l23_t3f_goodbye","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=sad|out=part",{1,"Will we see you again?",3,"Maybe",2,"Take care of yourself...",3,"I will",1,"Thank you for everything",3,"It's my job"}},
{"fw_l23_t3f_two_roads","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=calm|world=cars,water,road|out=walk",{1,"Which road is clear, the Brandenburg pike or the old quarry road?",3,"I can't give either one an all clear",2,"We came off the quarry road an hour ago. That tells you what we saw then, not what's there now",1,"Could somebody walk with us a while?",3,"I could walk a while. We'd still have to look for ourselves",2,"Then we'll keep together without pretending a crowd makes us safe"}},
{"fw_l23_t3f_broken_glass","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=fear|out=part",{2,"Somebody's been through the pharmacy, glass all over the floor",1,"Was it the sick ones?",3,"No, they don't take pills!",1,"Then somebody living",3,"Which is worse! Keep your eyes up",2,"And your voices down"}},
{"fw_l23_t3e_share_the_barn","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,12|mood=calm|world=door,stairs,building|out=part",{1,"We've been sleeping in the hayloft at the Lowe farm",2,"We found a root cellar two fields over, dry, and the door bars shut",3,"Anywhere with one door and a way out the other side - that's what I'd pick",1,"The hayloft has a ladder we can pull up",2,"Our cellar has a trapdoor",3,"Then you both have a plan, stick to it"}},
{"fw_l23_t3e_bring_the_pastor","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|x2=f|day=0,14|mood=warm|out=walk",{1,"Is Reverend Boone alive? Somebody said he was",2,"He's at the Baptist church, I saw him yesterday",3,"I'll take you both, it's on my route",1,"He married my daughter",2,"He buried my husband",3,"Then he's the right person to see - stay close"}},
{"fw_l23_t3e_what_is_in_that_truck","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,8|mood=grim|world=vehicle|out=stay3",{3,"Step away from that truck, please",1,"It's ours, we just stopped to rest",2,"What's in the back?",3,"I'd like to know too",1,"Just blankets and our canned goods",3,"Then show me - slowly"}},
{"fw_l23_t3e_found_a_phone_booth","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|hour=4,11|mood=funny|out=part",{1,"Tried calling my mother from the phone booth by the bank - dead",2,"Same one? I did that this morning",3,"I tried it yesterday, I'll admit",1,"Why do we all keep trying?",2,"Because it's a phone",3,"And because it's habit"}},
{"fw_l23_t3e_bigger_group","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,12|hour=16,5|mood=warm|out=walk",{1,"Anybody want company for a while?",2,"Can we join?",3,"Depends. You going to argue the whole way?",1,"I'll try not to",2,"I can't promise that",3,"Then let's walk before you get started"}},
{"fw_l23_t3e_curfew_conflict","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|mood=angry|world=building,cold|out=part",{1,"Why can't we have a fire? It's freezing in there!",2,"Because it draws them",3,"He's right! You can have a stove if it's indoors and vented",1,"We don't have a stove!",3,"Then sit close together and share the blankets",2,"It's what we're doing!"}},
{"fw_l23_t3e_missing_neighbors","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|hour=16,5|mood=sad|world=road|out=part",{1,"We haven't seen the Hendersons since Thursday...",2,"They were on my street too",3,"I'll check their house tonight",1,"You don't gotta do that",3,"It's part of the job",2,"Thank you for caring"}},
{"fw_l23_t3e_deputy_rumor","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,8|mood=grim|world=road|out=part",{1,"People are saying you've been shooting looters",3,"That's not true",2,"Someone said they saw a body in the road",3,"The body was infected... nothing to do with looting",1,"We believe you",3,"Spread the truth, then"}},
{"fw_l23_t3e_the_lights","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,8|hour=16,5|mood=fear|world=road,generator|out=part",{1,"Someone's got lights on at the end of the road",2,"A generator",3,"Or a trap!",1,"Should we go look?",3,"Not tonight",2,"Not ever, maybe!"}},
{"fw_l23_t3e_boys_and_bikes","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|mood=funny|out=part",{1,"Two boys on bikes just rode right through the yard",2,"Did they see you?",3,"Hard to say, they were pretty fast",1,"Should someone tell them it's dangerous?",3,"I will if I catch them",2,"You won't catch them, they're on bikes"}},
{"fw_l23_t3e_bad_water","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|mood=calm|world=water,rain|out=part",{1,"The creek water is brown - is it safe if we boil it?",3,"Boil it hard and strain it through cloth",2,"What about the rain barrels?",3,"Rain barrels are better than the creek",1,"Then we use the barrels",3,"Cover them so nothing falls in"}},
{"fw_l23_t3e_hardware_run","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,12|mood=calm|world=window|out=walk",{1,"We need nails and plywood to board the windows",2,"The hardware store on Third is open",3,"I'll escort you - stay together",1,"Do we take a cart?",2,"Take two",3,"Then let's go"}},
{"fw_l23_t3_whats_going_on","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=fear|out=stay3",{1,"What the hell is this?! Somebody tell me what's going on!",2,"Folks, we're trying to find that out ourselves",3,"Everyone stays calm - who's in charge here?",2,"I'm the closest thing - county deputy",3,"Deputy, I need your civilians behind my vehicle line",1,"They got my mother - please, they got my brother too",2,"Come with me, ma'am, walk slow"}},
{"fw_l23_t3_who_has_authority","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=angry|world=building|out=part",{1,"Who do I listen to, the badge or the uniform?",2,"I'm county! He's federal",3,"In this area my orders take priority, Deputy",2,"Then say it to her face, Sergeant",3,"Ma'am, stay inside and let us handle it",1,"And if I don't have a roof anymore?",3,"Then the deputy will find you one"}},
{"fw_l23_t3_quarantine_news","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=grim|out=part",{1,"Is it true the Army's closing the county?",3,"There is a quarantine order, ma'am",2,"It came through yesterday, we weren't consulted",3,"It's a federal matter - please stay within the county line",1,"What about the people who got caught outside it?",2,"We've had no word on them"}},
{"fw_l23_t3_dont_follow_me","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=calm|world=road|out=stay3",{1,"Can we come with you? You seem to know what you're doing",3,"Negative, we're moving into hostile territory",2,"He's right - go back to your homes",1,"We don't have homes anymore",2,"There's a shelter on the north side - take Elm to the church",3,"Road only, don't cut across the grass"}},
{"fw_l23_t3_checkpoint_dispute","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=angry|out=stay2",{1,"If another checkpoint turns us back, how do we get through to my sister?",3,"Don't try to push through an armed line, ma'am",2,"Sergeant, they ought to be able to ask somebody",3,"Ask, yes. I can't promise anyone else's answer, Deputy",2,"I'd try to explain who they are",3,"Then explain. Don't hand them a guarantee you can't keep"}},
{"fw_l23_t3_gunfire_east","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=fear|out=part",{2,"Was that you shooting east of town?",3,"Negative, we heard it too!",1,"It sounded like a lot of guns!",2,"Everybody get low - let me radio it in",3,"There's no channel to radio, Deputy",2,"I'll try anyway"}},
{"fw_l23_t3_share_a_meal","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|mood=warm|out=part",{1,"If I ever get a pot of stew going again, would you boys sit down to it?",2,"I'd be grateful. I miss a proper hot meal",3,"Make room for the deputies before you worry about me",1,"Don't be silly, there'd be room for you too",3,"One bowl, if I could spare the time",2,"Hear that? We've got him planning supper already"}},
{"fw_l23_t3_missing_boy","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|hour=4,11|mood=sad|out=stay2",{1,"I remember a woman looking for her son. Eleven, red shirt",2,"Where had she last seen him?",1,"A park. They were running and she lost his hand",3,"Not finding him there wouldn't tell you what happened",2,"No. That's why she kept asking everyone",3,"Eleven, red shirt. Some descriptions stay with you"}},
{"fw_l23_t3_rumor_evac","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=angry|world=cars|out=part",{1,"They said on the radio there'd be an evacuation at the high school",2,"I heard that too, there are no buses",3,"I can confirm there is no evacuation scheduled",1,"Then why did they say it?",3,"Someone made a mistake!",2,"Or lied!"}},
{"fw_l23_t3_the_dead_dont","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=grim|out=stay3",{1,"I shot one in the chest and it kept coming!",3,"Aim for the head - every time",2,"He's right, I wasted a lot of rounds learning it",1,"Why didn't anyone say so?",3,"We're saying so now",2,"Pass it on to everyone you meet"}},
{"fw_l23_t3_burn_it","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=fear|out=part",{1,"Did you see the smoke? The whole neighborhood is burning!",2,"The fire department was hit hard... nobody to put it out",3,"We started some of those fires to deny them cover",1,"You what? People live there!",3,"Nobody was inside - we checked",2,"I'll want that in writing, Sergeant"}},
{"fw_l23_t3_stay_out_of_town","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=calm|out=stay3",{1,"We were going to go through town to find my mother's pills",2,"Don't go in assuming the way is clear",3,"And don't count on a uniform getting you through",1,"She'll die without them",2,"I'd look for a pharmacy before trying the middle of town. But I can't tell you one is open",3,"Find out what you can before you commit to the trip"}},
{"fw_l23_t3_hear_that","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=fear|out=part",{1,"Quiet - did you hear that?",2,"Somebody moving in the bushes!",3,"Weapons ready! Nobody fires without a target",1,"What if it's a person?",2,"Then they'll answer when I call",3,"And if not, we'll know soon enough"}},
{"fw_l23_t3_trust_the_army","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=angry|out=part",{1,"Are you going to help us or not?",3,"Our mission is to contain the outbreak",1,"That's no answer!",2,"She's asking if you'll protect us!",3,"We'll protect what we can!",1,"Which isn't much"}},
{"fw_l23_t3_generator","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,12|mood=calm|world=generator|out=walk",{1,"If we got a generator working for a church shelter, how would we keep it fueled?",2,"We'd have to find out who actually had fuel",3,"And how much they could spare. I couldn't authorize ten gallons out of somebody else's drum",1,"I wouldn't want thanks for fuel we hadn't found",3,"Especially if somebody was counting on it for medical equipment",2,"Check the supply before making the promise. Then work out the trip"}},
{"fw_l23_t3_dog_tags","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,12|mood=sad|out=part",{1,"My husband was Army - he's missing - do you know of any units around Fort Knox?",3,"I might - what's his name?",1,"Gary Whitfield - Corporal...",3,"I don't recognize it, but I'll ask my captain",2,"I'll take down his description in case he turns up on our side",1,"Thank you both"}},
{"fw_l23_t3_blame","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=angry|out=part",{1,"Whose fault is this? Somebody did this!",2,"Ma'am, I don't have that answer",3,"Speculation won't help anyone!",1,"People deserve to know!",3,"And when I know, I'll tell you, right now I know nothing",2,"Same here!"}},
{"fw_l23_t3_split_the_street","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=calm|world=road|out=stay3",{2,"Let's divide the street, I'll take the east side",3,"My squad has the west",1,"What about us?",3,"Stay between the two lines",2,"You'll be safest in the middle",1,"Between the guns - wonderful"}},
{"fw_l23_t3_sunset","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|hour=16,5|mood=grim|out=part",{1,"It's getting dark - what do we do?",2,"Everyone inside before the streetlights come on",3,"No lights, no fire, no noise",1,"How long do we have to live like this?",3,"I can't say",2,"Just through the night, we'll reassess in the morning"}},
{"fw_l23_t3_dead_soldier","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=sad|world=water|out=stay3",{1,"I saw a soldier lying by a creek once. Young, maybe nineteen",3,"Were you able to help him?",2,"We tried. Couldn't even find out his name",3,"That's a hard thing to carry",1,"I still wonder if he was one of yours",3,"Somebody's, anyway. That's enough reason to remember him"}},
{"fw_l23_t3_wrong_side","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=angry|world=vehicle|out=part",{1,"You people shot at my brother's car!",3,"Which car?",1,"The blue Ford at the overpass!",2,"Sergeant, the Walsh boy drove a blue Ford",3,"... A sentry may have fired a warning, I'll look into it",1,"A warning? He's in the hospital"}},
{"fw_l23_t3_hold_hands","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|mood=warm|out=part",{1,"Would you all mind if I said a prayer for us?",2,"Go on",3,"Make it brief",1,"Dear Lord, keep these men safe, and us with them - forgive the rest",3,"Amen",2,"Amen"}},
{"fw_l23_t3_who_goes_first","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=calm|out=stay3",{2,"We're going to clear the barn",3,"We'll go first, Deputy",2,"It's my county",3,"And it's my rifle",1,"Please don't fight about it, just do it",2,"... After you, Sergeant"}},
{"fw_l23_t3_need_medic","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=fear|out=walk",{1,"My friend was bitten on the hand - is there a doctor?",3,"Medic is at the school!",2,"I'll radio the school, we'll bring him in",3,"We escort him, he doesn't walk alone",1,"Please be quick!",2,"Move out!"}},
{"fw_l23_t3_dont_hurt_him","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=sad|out=stay2",{1,"That's my neighbor! He's still in there! Don't shoot!",3,"Ma'am, he isn't the same",2,"Let me talk to him first...",3,"Deputy, no",2,"I knew him thirty years - give me one minute",3,"... One minute"}},
{"fw_l23_t3_coffee_and_orders","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|mood=funny|out=part",{1,"You boys want coffee? It's strong enough to strip paint",2,"Always",3,"Negative - on watch",2,"Sergeant, it's coffee, not a bribe",3,"Fine, one cup, black",1,"That's what I like to hear"}},
{"fw_l23_t3_peace_treaty","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,12|mood=warm|out=part",{2,"We seem to be getting along",3,"This is a temporary alignment of interests",1,"That's a very Army way to say friends",3,"... Associates",2,"I'll take it",1,"So will I"}},
{"fw_l23_t3_the_map","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,12|mood=calm|world=trees,road|out=walk",{1,"I know the back roads, I can lead you to the pump station",3,"How far?",1,"Two miles, tree cover most of the way",2,"I'll ride along - Sergeant, can you spare a driver?",3,"Granted, private, you're with them",1,"Follow me"}},
{"fw_l23_t3_pass_it_on","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|hour=16,22|mood=calm|out=part",{3,"Pass the word, curfew at dusk",2,"I'll tell my men",1,"And I'll tell the neighbors",3,"Anyone caught outside after dark is a target",2,"A harsh phrase, Sergeant",3,"It's a harsh situation"}},
{"fw_l23_t3_come_with_us","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,14|mood=warm|world=vehicle|out=stay1",{2,"Ma'am, we can take you as far as the church",3,"Space for two in the vehicle",1,"There are four of us",2,"Then two ride and two walk behind us",3,"Move quickly",1,"God bless you both"}},
{"fw_l23_t3_bite_check","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=fear|out=stay3",{3,"Everyone roll up your sleeves - bite check",1,"Is this really necessary?",2,"It is, it's for your safety",3,"Roll them up now!",1,"Fine, fine",2,"Clean - all clean - thank you"}},
{"fw_l23_t3d_monsters_all_over","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,6|mood=fear|world=water|out=stay3",{1,"I remember a woman screaming that they'd got her mother and brother",2,"Could she tell you where?",1,"By a creek, she said. An hour before she found us",3,"She wanted us to take over, like a uniform meant we had a plan",2,"I wanted to promise her a safe room. Hadn't even checked where we could go",1,"She kept saying, please don't leave us. I still hear that"}},
{"fw_l23_t3d_split_jobs","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=calm|out=part",{3,"Deputy, I need your people on crowd control",2,"Understood - Sergeant, can you cover the north entrance?",3,"Affirmative",1,"What can we do?",2,"Stay quiet and out of the way",1,"That we can do"}},
{"fw_l23_t3d_old_woman","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,14|mood=warm|out=walk",{1,"My mother can't walk far, she needs a chair",2,"There's a wheelchair in the lobby of the bank",3,"I'll send a man for it",1,"God bless you",3,"Wait here, ma'am, nobody moves until he's back",2,"She's in good hands"}},
{"fw_l23_t3d_wire_the_road","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,12|mood=calm|world=vehicle,road|out=stay3",{3,"I need concertina wire across this road",2,"The county garage used to keep a spool. I wouldn't count on it still being there",1,"If we find wire and a truck, I could drive",3,"We'd need someone riding with you, not another person sent off alone",2,"And a good look at the road before we load anything",1,"Yes, sir. A plan first, not just an order"}},
{"fw_l23_t3d_family_reunion","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,10|mood=warm|out=part",{1,"There! That's my sister! Oh, thank God!",2,"Ma'am, wait for the all-clear",3,"Let her through, Deputy, it's a family",1,"Oh, Tammy!",2,"Make it quick, and no noise",3,"We'll be watching"}},
{"fw_l23_t3d_whose_dog","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|mood=funny|world=road|out=part",{2,"Whose dog is that?",3,"He's been following my squad since the highway",1,"That's Mister Biggs! He belongs to the Carters on Alder",3,"He's been eating our rations",2,"He's not the first",1,"I'll take him home"}},
{"fw_l23_t3d_cold_night","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,10|mood=sad|world=building,cold|out=part",{1,"It's going to be a cold night - do you have blankets?",3,"Not enough",2,"There are some in the VFW basement...",1,"Then let's get them",3,"Deputy, escort them",2,"On it"}},
{"fw_l23_t3d_gate_guard","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|x1=f|day=0,8|mood=angry|out=stay3",{3,"Nobody enters without a bite check",1,"But we live there!",2,"Ma'am, it's for everyone's safety!",1,"You're treating us like criminals!",3,"We're treating you like people we'd like to keep alive",2,"Sleeves up, please!"}},
{"fw_l23_t3d_last_call","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,8|mood=grim|out=part",{1,"Is this it? Is this the end of everything?",2,"Don't think so, no",3,"No one here thinks so",1,"Then why does it feel like it?",2,"Because it's night",3,"And because you're tired, we all are"}},
{"fw_l23_t3d_beer_and_bullets","meet",3,"r1=civilian,family,worker|r2=law,swat|r3=military,elite|day=0,14|mood=funny|world=vehicle|out=part",{2,"I found a case of beer in the cruiser's trunk - confiscated from a party",3,"Contraband?",2,"Evidence",1,"May I have one?",3,"... We were never here",2,"I'll mark it consumed"}},
{"fw_l23_t3b_two_families_law","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,12|hour=16,5|mood=fear|world=building,road|out=part",{1,"We came off the Rosewood road, lost our car at the bridge",2,"We came the other way, same story, different bridge",3,"Both of you stay together - don't wander off alone",1,"Is it safe to share a roof tonight?",3,"Safer than apart - count heads every hour",2,"We'll do that"}},
{"fw_l23_t3b_who_has_water","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|mood=calm|world=road,rain|out=walk",{1,"We have a rain barrel behind the house, it's half full",2,"We've got filters but nothing to filter",3,"Combine what you have, I'll walk you both over",1,"It's only two streets",3,"Two streets is plenty if you're alone",2,"Agreed - let's go"}},
{"fw_l23_t3b_rumor_chain","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|hour=16,5|mood=grim|out=part",{1,"I heard the Army's not coming back",2,"I heard it was the sheriff's fault",3,"Neither is confirmed, and neither will help you eat tonight",1,"Then what will?",3,"Stay in your homes and share what you have",2,"Easier said"}},
{"fw_l23_t3b_break_the_tie","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|mood=angry|out=stay3",{1,"This is our well, we dug it",2,"We have kids who haven't drunk since morning",3,"Folks, the well belongs to whoever uses it quietly",1,"That's not a rule",3,"It is today! Share it, post a watch, keep your voices down",2,"Fine!"}},
{"fw_l23_t3b_lost_dog","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|mood=funny|out=part",{1,"Has anyone seen a beagle? Brown and white, answers to Biscuit",2,"There was a dog behind the bakery",3,"A beagle, you say, I saw him sniffing a shoe near the courthouse",1,"That's him!",3,"He seemed content",2,"Dogs usually are"}},
{"fw_l23_t3b_trade_post","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|mood=warm|world=road|out=walk",{1,"If we ever set up a trade table, would people bring what they could spare?",2,"Maybe. I'd ask what they needed before promising bandages or coffee",3,"And agree who watches while people trade. Nobody stops looking just because there's a table",1,"You'd make a fair deputy at a swap meet",3,"I'd settle for nobody getting hurt",2,"That's a better promise to try than everybody getting what they want"}},
{"fw_l23_t3b_burned_house","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|mood=sad|out=part",{1,"That used to be our house, it burned down Friday night",2,"I'm so sorry",3,"Anyone hurt?",1,"Not that we know of, we were out",3,"Count that as a mercy...",2,"It is"}},
{"fw_l23_t3b_dusk_rules","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|hour=16,22|mood=calm|world=door,window|out=stay3",{3,"Everybody listen, at dusk, doors locked, lights out",1,"What about the babies?",3,"Keep them quiet, blankets over the window",2,"We'll make sure",1,"How long will this last?",3,"I wish I knew"}},
{"fw_l23_t3b_church_rumor","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|hour=16,5|mood=warm|out=part",{1,"People are gathering at the church tonight",2,"Is it safe?",3,"I'll be there, I'm told the pastor's still preaching",1,"Then we'll come",2,"We'll bring a casserole",3,"I'll bring my sidearm and keep it quiet"}},
{"fw_l23_t3b_the_sniper","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,8|mood=fear|world=vehicle|out=part",{1,"Someone shot at us from the water tower!",2,"We all heard it!",3,"Down! Everyone get behind the truck!",1,"Is it one of theirs?",3,"I don't know whose it is",2,"Don't move!"}},
{"fw_l23_t3b_wounded_stranger","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,10|mood=sad|out=walk",{1,"There's a man in the ditch, he's hurt but he's talking...",2,"Is he bitten?",3,"Let me look, stay back",1,"He says he's not",3,"Then we carry him to the aid station - lift on three",2,"Let's go"}},
{"fw_l23_t3b_old_school","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,14|mood=warm|out=part",{1,"Deputy, didn't you coach Little League?",3,"Eight years - the Eagles",2,"You coached my boy!",3,"Ricky? The shortstop?",2,"That's him",3,"Tell him I said keep his head up"}},
{"fw_l23_t3b_whistle","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=law,swat|day=0,12|mood=calm|out=part",{3,"Two short whistles means danger, one long means clear",1,"Got it",2,"Short for danger, long for clear",3,"Don't whistle for any other reason",1,"Understood",2,"I'll teach the kids"}},
{"fw_l23_t3c_two_groups_army","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=fear|out=part",{1,"We came from the north side, it's all fire up there",2,"We came from the south, nothing but the sick ones",3,"Both groups return to your homes - remain indoors",1,"Our homes are gone!",3,"Then stick together, don't go off alone",2,"We'll try"}},
{"fw_l23_t3c_ration_line","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=grim|out=stay3",{3,"We have a ration line at noon, one per family",1,"We're four",2,"Six of us",3,"One per family - Elect a leader",1,"Fine, he'll be ours",2,"And ours is the woman at the back"}},
{"fw_l23_t3c_find_a_radio","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,12|mood=calm|world=vehicle,generator|out=walk",{1,"We have a ham radio but no power",3,"We have a generator - bring it by the truck",2,"Is that safe?",3,"Right behind me, all of you",1,"Lead the way",3,"Quietly"}},
{"fw_l23_t3c_neighbors_again","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,14|mood=warm|out=part",{1,"Is that you, Carol? From the Methodist choir?",2,"Margaret! I thought you'd moved to Frankfort",1,"I did, two years ago, I came back for my sister",3,"Reunions are fine - keep them quiet",2,"Yes, sir",1,"Yes, sir"}},
{"fw_l23_t3c_search_lane","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=calm|out=stay3",{3,"I need your names and where you're from",1,"Dennis Bock, Riverside",2,"Nell Pruitt, Rosewood",3,"Good, don't wander without telling me",1,"Where would we go?",3,"Nowhere, ideally"}},
{"fw_l23_t3c_dont_cross","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=fear|out=part",{1,"We were thinking of crossing the field",3,"Don't, there's a pack in the corn",2,"How many?",3,"I counted nineteen... maybe more",1,"Then we go around!",3,"Smart"}},
{"fw_l23_t3c_burial_detail","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=sad|out=part",{1,"Where do we bury our dead?",3,"Behind the church, there's a detail digging...",2,"Is it respectful?",3,"As respectful as we can manage...",1,"Thank you, Sergeant",3,"It's the least I can do"}},
{"fw_l23_t3c_broadcast_tonight","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,12|mood=calm|out=part",{3,"There's an emergency broadcast at nine on the AM band",1,"What will it say?",3,"I'm told it'll repeat the quarantine order",2,"We've heard that one",3,"Then you know it already",1,"Yes, sir"}},
{"fw_l23_t3c_counting_heads","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|mood=calm|world=building|out=stay3",{3,"Everyone gather by the wall, I'm taking a head count",1,"Eleven here",2,"Nine",3,"Twenty - any wounded?",1,"Two, minor",3,"Send them to the aid station"}},
{"fw_l23_t3c_dry_humor","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,14|mood=funny|out=part",{1,"Do you boys eat?",3,"When we have time",2,"You're thin",3,"I'm told it's the uniform",1,"If I had a sandwich, I'd make you eat it",3,"Then I'd have to admit the uniform wasn't the whole problem"}},
{"fw_l23_t3c_night_watch","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,10|hour=16,22|mood=grim|out=stay3",{3,"We need volunteers for night watch",1,"I can do two hours",2,"I'll do three",3,"Fine, you report to me at dusk",1,"Who do I wake?",3,"Me - always me"}},
{"fw_l23_t3c_last_stand","meet",3,"r1=civilian,family,worker|r2=civilian,family,worker|r3=military,elite|day=0,8|mood=fear|world=road|out=part",{1,"What happens if they overrun this street?",3,"We fall back to the church",2,"And then?",3,"Then we hold the church",1,"And then?",3,"Then we find another church!"}},
}
